import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type EquipmentType = 'machine' | 'tool' | 'vehicle';

export interface Equipment {
  id: string;
  name: string;
  type: EquipmentType;
  isActive: boolean;
}

export interface Reservation {
  id: string;
  resourceId: string; // Equipment ID or Scaffolding Location
  resourceName: string; // Denormalized for display
  type: 'workshop' | 'scaffolding';
  date: string; // YYYY-MM-DD
  startTime: string; // HH:mm
  endTime: string; // HH:mm
  requester: string;
  scaffoldingType?: 'assembly' | 'disassembly'; // Only for scaffolding
  createdAt?: string;
}

export interface CalendarDay {
  date: Date;
  isCurrentMonth: boolean;
  isToday: boolean;
  hasReservation: boolean;
  reservationCount: number;
}

export const HOURS = [
  '07:00', '08:00', '09:00', '10:00', '11:00', '12:00',
  '13:00', '14:00', '15:00', '16:00', '17:00', '18:00', '19:00'
];

export const MASTER_PASSWORD = '1234';

export const DAYS_OF_WEEK = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'];

export const INITIAL_EQUIPMENT = [
  { id: '1', name: 'Elevador Automotivo 1', type: 'machine', isActive: true },
  { id: '2', name: 'Elevador Automotivo 2', type: 'machine', isActive: true },
  { id: '3', name: 'Scanner de Diagnóstico', type: 'tool', isActive: true },
  { id: '4', name: 'Solda MIG/MAG', type: 'tool', isActive: true },
  { id: '5', name: 'Macaco Hidráulico', type: 'tool', isActive: true },
];

import { createClient } from '@supabase/supabase-js';

// NOTA: Em um ambiente de produção real, estas chaves estariam em um arquivo .env
// O usuário deve criar um arquivo .env com VITE_SUPABASE_URL e VITE_SUPABASE_KEY
// Para este demo, usaremos fallback para garantir que o código compile, 
// mas a conexão falhará se as chaves não forem providas.

const supabaseUrl = import.meta.env.VITE_SUPABASE_URL || 'https://ghgyiscnzcwokillnlox.supabase.co';
const supabaseKey = import.meta.env.VITE_SUPABASE_KEY || ''; // O usuário precisa inserir a chave aqui ou no .env

export const supabase = createClient(supabaseUrl, supabaseKey);

export const isSupabaseConfigured = () => {
  return supabaseUrl && supabaseKey && supabaseKey.length > 0;
};

import { supabase, isSupabaseConfigured } from './supabaseClient';
import { Reservation, Equipment } from '../types';
import { INITIAL_EQUIPMENT } from '../constants';

// MOCK DATA STORAGE (Fallback if Supabase is not connected)
let mockReservations: Reservation[] = [];
let mockEquipment: Equipment[] = [...INITIAL_EQUIPMENT];

// Helpers
const parseTime = (time: string) => parseInt(time.replace(':', ''), 10);

export const checkOverlap = async (
  date: string,
  startTime: string,
  endTime: string,
  resourceId: string,
  excludeId?: string
): Promise<boolean> => {
  const start = parseTime(startTime);
  const end = parseTime(endTime);

  const existing = await getReservationsByDate(date);

  return existing.some(res => {
    if (res.id === excludeId) return false;
    if (res.resourceId !== resourceId) return false;

    const resStart = parseTime(res.startTime);
    const resEnd = parseTime(res.endTime);

    // Overlap logic: (StartA < EndB) and (EndA > StartB)
    return start < resEnd && end > resStart;
  });
};

// --- CRUD Operations ---

export const getEquipment = async (): Promise<Equipment[]> => {
  if (!isSupabaseConfigured()) return Promise.resolve(mockEquipment);

  const { data, error } = await supabase.from('equipment').select('*');
  if (error || !data) {
    console.warn("Using default equipment list due to fetch error or empty DB");
    return mockEquipment; // Fallback
  }
  return data.map((d: any) => ({
    id: d.id.toString(),
    name: d.name,
    type: d.type,
    isActive: d.is_active
  }));
};

export const saveEquipment = async (equip: Equipment): Promise<Equipment> => {
  if (!isSupabaseConfigured()) {
    mockEquipment.push(equip);
    return Promise.resolve(equip);
  }
  const { data, error } = await supabase.from('equipment').insert([{
    name: equip.name,
    type: equip.type,
    is_active: equip.isActive
  }]).select();

  if (error) throw error;
  return { ...equip, id: data[0].id.toString() };
};

export const deleteEquipment = async (id: string): Promise<void> => {
   if (!isSupabaseConfigured()) {
    mockEquipment = mockEquipment.filter(e => e.id !== id);
    return Promise.resolve();
  }
  await supabase.from('equipment').delete().eq('id', id);
};


export const getReservationsByDate = async (date: string): Promise<Reservation[]> => {
  if (!isSupabaseConfigured()) {
    return Promise.resolve(mockReservations.filter(r => r.date === date));
  }

  const { data, error } = await supabase
    .from('reservations')
    .select('*')
    .eq('date', date);

  if (error) {
    console.error("Error fetching reservations:", error);
    return [];
  }

  return data.map((r: any) => ({
    id: r.id.toString(),
    resourceId: r.resource_id,
    resourceName: r.resource_name,
    type: r.type,
    date: r.date,
    startTime: r.start_time,
    endTime: r.end_time,
    requester: r.requester,
    scaffoldingType: r.scaffolding_type
  }));
};

export const getAllReservations = async (): Promise<Reservation[]> => {
  if (!isSupabaseConfigured()) {
    return Promise.resolve(mockReservations);
  }
  const { data, error } = await supabase.from('reservations').select('*');
  if (error) return [];
  return data.map((r: any) => ({
    id: r.id.toString(),
    resourceId: r.resource_id,
    resourceName: r.resource_name,
    type: r.type,
    date: r.date,
    startTime: r.start_time,
    endTime: r.end_time,
    requester: r.requester,
    scaffoldingType: r.scaffolding_type
  }));
}

export const createReservation = async (res: Omit<Reservation, 'id'>): Promise<Reservation> => {
  // Validate Overlap
  const hasOverlap = await checkOverlap(res.date, res.startTime, res.endTime, res.resourceId);
  if (hasOverlap) {
    throw new Error("Conflito de horário detectado para este recurso.");
  }

  if (!isSupabaseConfigured()) {
    const newRes = { ...res, id: Math.random().toString(36).substr(2, 9) };
    mockReservations.push(newRes);
    return Promise.resolve(newRes);
  }

  const { data, error } = await supabase.from('reservations').insert([{
    resource_id: res.resourceId,
    resource_name: res.resourceName,
    type: res.type,
    date: res.date,
    start_time: res.startTime,
    end_time: res.endTime,
    requester: res.requester,
    scaffolding_type: res.scaffoldingType
  }]).select();

  if (error) throw error;

  return { ...res, id: data[0].id.toString() };
};

export const deleteReservation = async (id: string): Promise<void> => {
  if (!isSupabaseConfigured()) {
    mockReservations = mockReservations.filter(r => r.id !== id);
    return Promise.resolve();
  }
  const { error } = await supabase.from('reservations').delete().eq('id', id);
  if (error) throw error;
};

