  const [isDayModalOpen, setIsDayModalOpen] = useState(false);
  const [selectedDay, setSelectedDay] = useState<Date | null>(null);

  // Form State
  const [formData, setFormData] = useState({
    resourceId: '',
    startTime: '08:00',
    endTime: '09:00',
    requester: '',
    observation: ''
  });

  useEffect(() => {
    loadData();
  }, [currentDate]);

  const loadData = async () => {
    setLoading(true);
    try {
      const equip = await reservationService.getEquipment();
      setEquipmentList(equip.filter(e => e.type !== 'vehicle'));

      const allRes = await reservationService.getAllReservations();
      setReservations(allRes.filter(r => r.type === 'workshop'));
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleDayClick = (date: Date) => {
    setSelectedDay(date);
    // Reset form when opening modal for a new date
    setFormData({
      resourceId: '',
      startTime: '08:00',
      endTime: '09:00',
      requester: '',
      observation: ''
    });
    setIsDayModalOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedDay || !formData.resourceId) return;

    const dateStr = selectedDay.toISOString().split('T')[0];
    const resource = equipmentList.find(e => e.id === formData.resourceId);

    try {
      await reservationService.createReservation({
        resourceId: formData.resourceId,
        resourceName: resource?.name || 'Desconhecido',
        type: 'workshop',
        date: dateStr,
        startTime: formData.startTime,
        endTime: formData.endTime,
        requester: formData.requester,
        observation: formData.observation
      });
      alert("Reserva realizada com sucesso!");
      // Don't close modal immediately, allow user to see it or add another? 
      // User experience choice: close modal to show success on calendar.
      loadData();
      setIsDayModalOpen(false);
    } catch (err: any) {
      alert(err.message);
    }
  };

  const handleDelete = async (id: string) => {
    const pwd = prompt("Digite a senha mestre para cancelar:");
    if (pwd === MASTER_PASSWORD) {
      await reservationService.deleteReservation(id);
      loadData();
    } else {
      alert("Senha incorreta.");
    }
  };

  const reservationMap = reservations.reduce((acc, curr) => {
    acc[curr.date] = (acc[curr.date] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  const selectedDayReservations = selectedDay 
    ? reservations.filter(r => r.date === selectedDay.toISOString().split('T')[0])
    : [];

  return (
