            <div className="grid grid-cols-3 gap-4">
                <div className="col-span-1">
                    <label className="block text-xs font-bold text-slate-600 mb-1">Data *</label>
                    <input 
                        type="date"
                        disabled
                        value={selectedDay?.toISOString().split('T')[0] || ''}
                        className="w-full p-2.5 bg-orange-50 border border-slate-300 rounded-lg text-sm text-slate-500 cursor-not-allowed"
                    />
