                    >
                    {HOURS.slice(0, -1).map(h => <option key={h} value={h}>{h}</option>)}
                    </select>
                </div>
                <div className="col-span-1">
                    <label className="block text-xs font-bold text-slate-600 mb-1">Fim *</label>
                    <select 
                    className="w-full p-2.5 bg-white border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-orange-500 outline-none"
                    value={formData.endTime}
                    onChange={e => setFormData({...formData, endTime: e.target.value})}
                    >
                    {HOURS.slice(1).map(h => <option key={h} value={h}>{h}</option>)}
                    </select>
                </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block text-xs font-bold text-slate-600 mb-1">Solicitante *</label>
                    <input 
                        type="text" 
                        required
                        className="w-full p-2.5 bg-white border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-orange-500 outline-none"
                        placeholder="Nome"
                        value={formData.requester}
                        onChange={e => setFormData({...formData, requester: e.target.value})}
                    />
                </div>
                <div>
                    <label className="block text-xs font-bold text-slate-600 mb-1">Obs</label>
                    <input 
                        type="text" 
                        className="w-full p-2.5 bg-white border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-orange-500 outline-none"
                        value={formData.observation}
                        onChange={e => setFormData({...formData, observation: e.target.value})}
                    />
                </div>
            </div>

            <button type="submit" className="w-full bg-orange-600 hover:bg-orange-700 text-white font-bold py-3 rounded-lg transition-colors shadow-lg shadow-orange-500/30">
              Agendar
            </button>
          </form>

          {/* List existing */}
          {selectedDayReservations.length > 0 && (
             <div className="pt-4 border-t border-orange-100">
                <h5 className="text-xs font-bold text-slate-400 uppercase mb-2">Agendamentos do dia</h5>
                <div className="space-y-2 max-h-40 overflow-y-auto">
                    {selectedDayReservations.map(res => (
                        <div key={res.id} className="flex justify-between items-start bg-orange-50 p-2 rounded border border-orange-200 text-sm">
                        <div>
                            <span className="font-bold text-slate-800">{res.resourceName}</span>
                            <span className={`text-xs ml-2 font-bold px-1.5 py-0.5 rounded ${res.scaffoldingType === 'assembly' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                {res.scaffoldingType === 'assembly' ? 'Montagem' : 'Desmontagem'}
                            </span>
                            <div className="text-slate-500 text-xs mt-1">
                                {res.startTime}-{res.endTime} | {res.requester} {res.observation && `(${res.observation})`}
                            </div>
                        </div>
                        <button onClick={() => handleDelete(res.id)} className="text-red-400 hover:text-red-600">
                            <FaTrash size={12} />
                        </button>
                        </div>
                    ))}
                </div>
             </div>
          )}
        </div>
      </Modal>
    </div>
  );
};

export default Scaffolding;

