// VITE_SUPABASE_KEY=sua_chave_anon_aqui

const supabaseUrl = (import.meta as any).env?.VITE_SUPABASE_URL || '';
const supabaseKey = (import.meta as any).env?.VITE_SUPABASE_KEY || '';

// Verifica se as chaves existem e não são strings vazias
const hasValidKey = supabaseUrl.length > 0 && supabaseKey.length > 0;

if (!hasValidKey) {
  console.log("⚠️ Supabase: Credenciais não encontradas. O app funcionará em modo OFFLINE (Local Storage).");
}

// Se não tiver chave, criamos um cliente dummy que não crasha o app, mas as chamadas falharão (e o service tratará)
export const supabase = createClient(
    hasValidKey ? supabaseUrl : 'https://placeholder.supabase.co', 
