// Chaves do LocalStorage (permitindo configuração via UI)
const LOCAL_CONFIG_KEY = 'oficina_supabase_config';

const getLocalConfig = () => {
    try {
        const stored = localStorage.getItem(LOCAL_CONFIG_KEY);
        return stored ? JSON.parse(stored) : null;
    } catch {
        return null;
    }
};

const localConfig = getLocalConfig();

// Prioridade: Variáveis de Ambiente > Configuração Local (UI) > Vazio
const envUrl = (import.meta as any).env?.VITE_SUPABASE_URL;
const envKey = (import.meta as any).env?.VITE_SUPABASE_KEY;

const supabaseUrl = envUrl || localConfig?.url || '';
const supabaseKey = envKey || localConfig?.key || '';

// Verifica se as chaves existem e não são strings vazias
const hasValidKey = supabaseUrl.length > 0 && supabaseKey.length > 0;

if (!hasValidKey) {
  console.log("⚠️ Supabase: Credenciais não encontradas. O app funcionará em modo OFFLINE (Local Storage).");
} else {
  console.log("✅ Supabase: Credenciais configuradas.");
}

// Se não tiver chave, criamos um cliente dummy
export const supabase = createClient(
    hasValidKey ? supabaseUrl : 'https://placeholder.supabase.co', 
    hasValidKey ? supabaseKey : 'placeholder-key'
);

export const isSupabaseConfigured = () => {
  return hasValidKey;
};

// Helpers para a UI de Configuração
export const getStoredSupabaseConfig = () => localConfig;

export const saveSupabaseConfig = (url: string, key: string) => {
    localStorage.setItem(LOCAL_CONFIG_KEY, JSON.stringify({ url, key }));
    window.location.reload(); // Recarrega para aplicar o novo cliente
};

export const clearSupabaseConfig = () => {
    localStorage.removeItem(LOCAL_CONFIG_KEY);
    window.location.reload();
};

import { supabase, isSupabaseConfigured } from './supabaseClient';
import { Reservation, Equipment } from '../types';
import { INITIAL_EQUIPMENT } from '../constants';

// --- LOCAL STORAGE HELPERS ---
const STORAGE_KEYS = {
  RESERVATIONS: 'oficina_sys_reservations_v2',
  EQUIPMENT: 'oficina_sys_equipment_v2'
};

const loadFromStorage = <T>(key: string, defaultVal: T): T => {
  try {
    const item = localStorage.getItem(key);
    return item ? JSON.parse(item) : defaultVal;
  } catch (e) {
    console.warn(`Failed to load ${key} from storage`, e);
    return defaultVal;
  }
};

const saveToStorage = (key: string, data: any) => {
  try {
    localStorage.setItem(key, JSON.stringify(data));
  } catch (e) {
    console.warn(`Failed to save ${key} to storage`, e);
  }
};

// INITIALIZATION
let mockReservations: Reservation[] = loadFromStorage(STORAGE_KEYS.RESERVATIONS, []);
let mockEquipment: Equipment[] = loadFromStorage(STORAGE_KEYS.EQUIPMENT, [...INITIAL_EQUIPMENT]);

// Helpers
const parseTime = (time: string) => parseInt(time.replace(':', ''), 10);

export const checkOverlap = async (
  date: string,
  startTime: string,
  endTime: string,
  resourceId: string,
  excludeId?: string
): Promise<boolean> => {
  const start = parseTime(startTime);
  const end = parseTime(endTime);

  const existing = await getReservationsByDate(date);

  return existing.some(res => {
    if (res.id === excludeId) return false;
    if (res.resourceId !== resourceId) return false;

    const resStart = parseTime(res.startTime);
    const resEnd = parseTime(res.endTime);

    return start < resEnd && end > resStart;
  });
};

// --- CRUD Operations ---

export const getEquipment = async (): Promise<Equipment[]> => {
  // 1. If Offline, refresh from storage explicitly to ensure UI is in sync
  if (!isSupabaseConfigured()) {
    mockEquipment = loadFromStorage(STORAGE_KEYS.EQUIPMENT, [...INITIAL_EQUIPMENT]);
    return Promise.resolve([...mockEquipment]);
  }

  // 2. If Online, try to fetch
  try {
    const { data, error } = await supabase
      .from('equipment')
      .select('*')
      .order('name', { ascending: true });

    if (error) throw error;

    if (!data) return [];

    return data.map((d: any) => ({
      id: d.id.toString(),
      name: d.name,
      type: d.type,
      isActive: d.is_active
    }));
  } catch (e) {
    console.warn("Supabase fetch error (using local fallback):", e);
    return [...mockEquipment];
  }
};

export const saveEquipment = async (equip: Equipment): Promise<Equipment> => {
  // Offline Mode
  if (!isSupabaseConfigured()) {
    const newEquip = { ...equip, id: equip.id || Math.random().toString(36).substr(2, 9) };
    // Reload latest before saving to avoid overwrites
    const current = loadFromStorage(STORAGE_KEYS.EQUIPMENT, [...INITIAL_EQUIPMENT]);
    mockEquipment = [...current, newEquip];
    saveToStorage(STORAGE_KEYS.EQUIPMENT, mockEquipment);
    return Promise.resolve(newEquip);
  }

  // Online Mode
  try {
    const { data, error } = await supabase.from('equipment').insert([{
      name: equip.name,
      type: equip.type,
      is_active: equip.isActive
    }]).select();

    if (error) throw error;
    return { ...equip, id: data[0].id.toString() };
  } catch (e) {
    console.error("Save failed, falling back to local storage", e);
    const newEquip = { ...equip, id: equip.id || Math.random().toString(36).substr(2, 9) };
    mockEquipment.push(newEquip);
    saveToStorage(STORAGE_KEYS.EQUIPMENT, mockEquipment);
    return newEquip;
  }
};

export const deleteEquipment = async (id: string): Promise<void> => {
   // Offline Mode
   if (!isSupabaseConfigured()) {
    console.log(`[OFFLINE] Deleting equipment ${id}`);
    // READ directly from storage to ensure we have the truth
    const current = loadFromStorage<Equipment[]>(STORAGE_KEYS.EQUIPMENT, [...INITIAL_EQUIPMENT]);
    // FILTER strict string comparison
    const updated = current.filter(e => String(e.id) !== String(id));
    // SAVE back
    saveToStorage(STORAGE_KEYS.EQUIPMENT, updated);
    // UPDATE memory
    mockEquipment = updated;
    return Promise.resolve();
  }

  // Online Mode
  try {
    const { error } = await supabase.from('equipment').delete().eq('id', id);
    if (error) throw error;

    // Also update local mock just in case
    const current = loadFromStorage<Equipment[]>(STORAGE_KEYS.EQUIPMENT, [...INITIAL_EQUIPMENT]);
    const updated = current.filter(e => String(e.id) !== String(id));
    saveToStorage(STORAGE_KEYS.EQUIPMENT, updated);
    mockEquipment = updated;
  } catch (e) {
    console.error("Delete failed on server, trying local force delete", e);
    // Force local delete if server fails
    const current = loadFromStorage<Equipment[]>(STORAGE_KEYS.EQUIPMENT, [...INITIAL_EQUIPMENT]);
    const updated = current.filter(e => String(e.id) !== String(id));
    saveToStorage(STORAGE_KEYS.EQUIPMENT, updated);
    mockEquipment = updated;
  }
};

export const getReservationsByDate = async (date: string): Promise<Reservation[]> => {
  if (!isSupabaseConfigured()) {
    mockReservations = loadFromStorage(STORAGE_KEYS.RESERVATIONS, []);
    return Promise.resolve(mockReservations.filter(r => r.date === date));
  }

  try {
    const { data, error } = await supabase
        .from('reservations')
        .select('*')
        .eq('date', date);

    if (error) throw error;

    return data.map((r: any) => ({
        id: r.id.toString(),
        resourceId: r.resource_id,
        resourceName: r.resource_name,
        type: r.type,
        date: r.date,
        startTime: r.start_time,
        endTime: r.end_time,
        requester: r.requester,
        scaffoldingType: r.scaffolding_type,
        observation: r.observation
    }));
  } catch (e) {
      console.warn("Reservation fetch failed, using mock:", e);
      return mockReservations.filter(r => r.date === date);
  }
};

export const getAllReservations = async (): Promise<Reservation[]> => {
  if (!isSupabaseConfigured()) {
    mockReservations = loadFromStorage(STORAGE_KEYS.RESERVATIONS, []);
    return Promise.resolve(mockReservations);
  }
  try {
    const { data, error } = await supabase.from('reservations').select('*');
    if (error) throw error;
    return data.map((r: any) => ({
        id: r.id.toString(),
        resourceId: r.resource_id,
        resourceName: r.resource_name,
        type: r.type,
        date: r.date,
        startTime: r.start_time,
        endTime: r.end_time,
        requester: r.requester,
        scaffoldingType: r.scaffolding_type,
        observation: r.observation
    }));
  } catch (e) {
      console.warn("Get all failed, using mock:", e);
      return mockReservations;
  }
}

export const createReservation = async (res: Omit<Reservation, 'id'>): Promise<Reservation> => {
  const hasOverlap = await checkOverlap(res.date, res.startTime, res.endTime, res.resourceId);
  if (hasOverlap) {
    throw new Error("Conflito de horário detectado para este recurso.");
  }

  if (!isSupabaseConfigured()) {
    const newRes = { ...res, id: Math.random().toString(36).substr(2, 9) };
    const current = loadFromStorage<Reservation[]>(STORAGE_KEYS.RESERVATIONS, []);
    mockReservations = [...current, newRes];
    saveToStorage(STORAGE_KEYS.RESERVATIONS, mockReservations);
    return Promise.resolve(newRes);
  }

  try {
    const { data, error } = await supabase.from('reservations').insert([{
        resource_id: res.resourceId,
        resource_name: res.resourceName,
        type: res.type,
        date: res.date,
        start_time: res.startTime,
        end_time: res.endTime,
        requester: res.requester,
        scaffolding_type: res.scaffoldingType,
        observation: res.observation
    }]).select();

    if (error) throw error;

    return { ...res, id: data[0].id.toString() };
  } catch (e) {
      console.error("Create failed, using mock", e);
      const newRes = { ...res, id: Math.random().toString(36).substr(2, 9) };
      mockReservations.push(newRes);
      saveToStorage(STORAGE_KEYS.RESERVATIONS, mockReservations);
      return newRes;
  }
};

export const deleteReservation = async (id: string): Promise<void> => {
  if (!isSupabaseConfigured()) {
    const current = loadFromStorage<Reservation[]>(STORAGE_KEYS.RESERVATIONS, []);
    mockReservations = current.filter(r => r.id !== id);
    saveToStorage(STORAGE_KEYS.RESERVATIONS, mockReservations);
    return Promise.resolve();
  }
  try {
    const { error } = await supabase.from('reservations').delete().eq('id', id);
    if (error) throw error;
  } catch (e) {
      console.error("Delete failed, using mock", e);
      mockReservations = mockReservations.filter(r => r.id !== id);
      saveToStorage(STORAGE_KEYS.RESERVATIONS, mockReservations);
  }
};

import React, { useState, useEffect } from 'react';
import { FaTrash, FaPlus, FaUndo, FaExclamationTriangle, FaCloud, FaLink, FaUnlink } from 'react-icons/fa';
import * as reservationService from '../services/reservationService';
import { saveSupabaseConfig, getStoredSupabaseConfig, clearSupabaseConfig, isSupabaseConfigured } from '../services/supabaseClient';
import { Equipment } from '../types';
import { INITIAL_EQUIPMENT } from '../constants';

const Settings: React.FC = () => {
  const [equipment, setEquipment] = useState<Equipment[]>([]);
  const [newEqName, setNewEqName] = useState('');
  const [newEqType, setNewEqType] = useState('machine');

  // Supabase Config State
  const [sbUrl, setSbUrl] = useState('');
  const [sbKey, setSbKey] = useState('');
  const [isConnected, setIsConnected] = useState(false);

  useEffect(() => {
    load();
    const config = getStoredSupabaseConfig();
    if (config) {
        setSbUrl(config.url);
        setSbKey(config.key);
    }
    setIsConnected(isSupabaseConfigured());
  }, []);

  const load = async () => {
    try {
        const data = await reservationService.getEquipment();
        setEquipment(data);
    } catch (error) {
        console.error("Error loading equipment:", error);
    }
  };

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEqName) return;

    try {
        await reservationService.saveEquipment({
            id: '', 
            name: newEqName,
            type: newEqType as any,
            isActive: true
        });
        setNewEqName('');
        // Reload strictly from source
        await load(); 
    } catch (e) {
        console.error(e);
        alert("Erro ao salvar.");
    }
  };

  const handleDelete = async (id: string) => {
    if (window.confirm("Tem certeza que deseja remover este equipamento?")) {
        try {
            await reservationService.deleteEquipment(id);
            // Reload strictly from source to confirm deletion
            await load();
        } catch (e) {
            console.error("Failed to delete", e);
            alert("Erro ao excluir. Tente novamente.");
        }
    }
  };

  const restoreDefaults = async () => {
    if (window.confirm("Isso irá recriar os equipamentos padrão localmente. Continuar?")) {
        for (const eq of INITIAL_EQUIPMENT) {
            await reservationService.saveEquipment(eq);
        }
        await load();
    }
  };

  const handleHardReset = () => {
    const confirmation = prompt("DIGITE 'RESET' para apagar todos os dados locais e recarregar o sistema. Isso não pode ser desfeito.");
    if (confirmation === 'RESET') {
        localStorage.clear();
        window.location.reload();
    }
  };

  const handleConnectSupabase = (e: React.FormEvent) => {
      e.preventDefault();
      if(sbUrl && sbKey) {
          saveSupabaseConfig(sbUrl, sbKey);
      }
  };

  const handleDisconnect = () => {
      if(window.confirm("Deseja desconectar do banco de dados? O app voltará para o modo offline.")) {
          clearSupabaseConfig();
      }
  };

  return (
    <div className="p-8 h-screen overflow-y-auto">
      <div className="flex justify-between items-center mb-6">
          <h1 className="text-3xl font-bold text-slate-800">Configurações</h1>
          <button 
            onClick={handleHardReset}
            className="text-xs bg-red-100 hover:bg-red-200 text-red-700 px-3 py-2 rounded flex items-center gap-2 border border-red-200 transition-colors"
          >
              <FaExclamationTriangle /> Resetar Sistema Completo
          </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">

        {/* Supabase Connection Panel - NEW */}
        <div className={`p-6 rounded-xl shadow-sm border transition-all ${isConnected ? 'bg-green-50 border-green-200' : 'bg-white border-slate-200'}`}>
            <h2 className="text-xl font-bold mb-4 text-slate-700 flex items-center gap-2">
                <FaCloud className={isConnected ? "text-green-600" : "text-slate-400"} />
                Integração Banco de Dados
            </h2>

            {isConnected ? (
                <div className="space-y-4">
                    <div className="text-sm text-green-800 bg-green-100 p-3 rounded border border-green-200">
                        <strong>Conectado!</strong><br/>
                        Seus dados estão sendo salvos na nuvem (Supabase).
                    </div>
                    <button 
                        onClick={handleDisconnect}
                        className="w-full flex items-center justify-center gap-2 bg-white text-red-600 border border-red-200 font-bold py-2 rounded hover:bg-red-50"
                    >
                        <FaUnlink /> Desconectar
                    </button>
                </div>
            ) : (
                <form onSubmit={handleConnectSupabase} className="space-y-4">
                    <p className="text-xs text-slate-500">
                        Para sincronizar com suas tabelas, insira as credenciais do seu projeto Supabase abaixo.
                    </p>
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Project URL</label>
                        <input 
                            value={sbUrl}
                            onChange={e => setSbUrl(e.target.value)}
                            className="w-full p-2 border border-slate-300 rounded text-sm"
                            placeholder="https://xyz.supabase.co"
                            required
                        />
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Anon API Key</label>
                        <input 
                            value={sbKey}
                            onChange={e => setSbKey(e.target.value)}
                            className="w-full p-2 border border-slate-300 rounded text-sm"
                            type="password"
                            placeholder="eyJh..."
                            required
                        />
                    </div>
                    <button type="submit" className="w-full flex items-center justify-center gap-2 bg-slate-800 text-white font-bold py-2 rounded hover:bg-slate-900">
                        <FaLink /> Salvar e Conectar
                    </button>
                </form>
            )}
        </div>

        {/* Add New Equipment */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h2 className="text-xl font-bold mb-4 text-slate-700">Adicionar Equipamento</h2>
          <form onSubmit={handleAdd} className="space-y-4">
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Nome</label>
              <input 
                value={newEqName}
                onChange={e => setNewEqName(e.target.value)}
                className="w-full p-2 border border-slate-300 rounded"
                placeholder="Ex: Torno Mecânico"
              />
            </div>
            <div>
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Tipo</label>
               <select 
                value={newEqType} 
                onChange={e => setNewEqType(e.target.value)}
                className="w-full p-2 border border-slate-300 rounded"
               >
                   <option value="machine">Máquina</option>
                   <option value="tool">Ferramenta</option>
                   <option value="vehicle">Veículo</option>
               </select>
            </div>
            <button type="submit" className="flex items-center justify-center gap-2 w-full bg-blue-600 text-white font-bold py-2 rounded hover:bg-blue-700 transition-colors">
                <FaPlus /> Adicionar
            </button>
          </form>
        </div>

        {/* List */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 md:col-span-2">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-bold text-slate-700">Equipamentos Ativos</h2>
            {equipment.length === 0 && !isConnected && (
                <button onClick={restoreDefaults} className="text-xs flex items-center gap-1 text-blue-500 hover:underline">
                    <FaUndo /> Restaurar Padrões Locais
                </button>
            )}
          </div>

          <div className="space-y-2 max-h-96 overflow-y-auto">
            {equipment.length > 0 ? (
                equipment.map(eq => (
                    <div key={eq.id} className="flex justify-between items-center p-3 bg-slate-50 rounded border border-slate-100 hover:border-slate-200 transition-colors">
                        <div>
                            <span className="font-semibold text-slate-700">{eq.name}</span>
                            <span className="text-xs text-slate-400 block uppercase">{eq.type}</span>
                        </div>
                        <button 
                            onClick={() => handleDelete(eq.id)} 
                            className="text-slate-300 hover:text-red-500 p-2 transition-colors cursor-pointer"
                            title="Excluir"
                        >
                            <FaTrash />
                        </button>
                    </div>
                ))
            ) : (
                <p className="text-slate-400 italic text-center py-4">Nenhum equipamento encontrado.</p>
            )}
          </div>
        </div>

      </div>
    </div>
  );
};

export default Settings;

