  }
};

export const deleteEquipment = async (id: string): Promise<void> => {
   const idStr = String(id);

   // 1. GARANTIA LOCAL: Adicionar à blacklist imediatamente
   // Isso garante que o item suma da UI mesmo se o banco falhar
   const blacklist = loadFromStorage<string[]>(STORAGE_KEYS.BLACKLIST, []);
   if (!blacklist.includes(idStr)) {
       blacklist.push(idStr);
       saveToStorage(STORAGE_KEYS.BLACKLIST, blacklist);
   }

   // 2. TENTATIVA NO SERVIDOR (Soft Delete)
   if (isSupabaseConfigured()) {
       try {
            const idParam = /^\d+$/.test(id) ? parseInt(id, 10) : id;
            await supabase
                .from('equipment')
                .update({ is_active: false })
                .eq('id', idParam);
       } catch (err) {
           console.warn("Erro ao atualizar status no banco (ignorado pois blacklist local resolveu):", err);
           // Não lançamos erro aqui para não assustar o usuário, já que visualmente foi resolvido.
       }
   }

   // 3. Atualizar cache local legado
   const current = loadFromStorage<Equipment[]>(STORAGE_KEYS.EQUIPMENT, [...INITIAL_EQUIPMENT]);
   const updated = current.map(e => String(e.id) === idStr ? { ...e, isActive: false } : e);
   saveToStorage(STORAGE_KEYS.EQUIPMENT, updated);
   mockEquipment = updated;

   return Promise.resolve();
};

