import React from 'react';
import { HOURS, DAYS_OF_WEEK } from '../constants';
import { Reservation } from '../types';

interface CalendarViewProps {
  currentDate: Date;
  onSlotClick: (date: Date, time: string) => void;
  onEventClick?: (reservation: Reservation) => void;
  reservations: Reservation[];
  themeColor: 'blue' | 'orange';
}

const CalendarView: React.FC<CalendarViewProps> = ({ 
  currentDate, 
  onSlotClick, 
  onEventClick,
  reservations, 
  themeColor 
}) => {
  // Helper: Get the start of the week (Sunday) based on currentDate
  const getStartOfWeek = (date: Date) => {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day; 
    return new Date(d.setDate(diff));
  };

  const startOfWeek = getStartOfWeek(currentDate);

  // Generate the 7 days of the current week
  const weekDays = Array.from({ length: 7 }, (_, i) => {
    const d = new Date(startOfWeek);
    d.setDate(d.getDate() + i);
    return d;
  });

  // Helper: Check if a reservation occupies a specific slot
  const getReservationForSlot = (date: Date, timeStr: string) => {
    const dateStr = date.toISOString().split('T')[0];
    const slotTime = parseInt(timeStr.split(':')[0], 10);

    return reservations.find(r => {
      if (r.date !== dateStr) return false;

      const start = parseInt(r.startTime.split(':')[0], 10);
      const end = parseInt(r.endTime.split(':')[0], 10);

      // Inclusive start, exclusive end (standard for time slots)
      return slotTime >= start && slotTime < end;
    });
  };

  // Styles based on theme
  const headerBg = themeColor === 'blue' ? 'bg-slate-100' : 'bg-orange-50';
  const borderColor = themeColor === 'blue' ? 'border-slate-200' : 'border-orange-200';

  const getEventStyle = () => {
    if (themeColor === 'blue') {
      return "bg-blue-100 border-l-4 border-blue-500 text-blue-800 hover:bg-blue-200";
    }
    return "bg-orange-100 border-l-4 border-orange-500 text-orange-800 hover:bg-orange-200";
  };

  return (
    <div className={`bg-white rounded-xl shadow-sm border ${borderColor} overflow-hidden flex flex-col h-full max-h-[calc(100vh-200px)]`}>
      {/* Header Row: Days of Week */}
      <div className="flex border-b border-slate-200">
        {/* Time Column Header */}
        <div className="w-20 flex-shrink-0 p-3 bg-slate-50 border-r border-slate-200"></div>

        {/* Days Headers */}
        <div className="flex-1 grid grid-cols-7 divide-x divide-slate-100">
          {weekDays.map((day, index) => {
            const isToday = new Date().toDateString() === day.toDateString();
            return (
              <div key={index} className={`p-2 text-center ${headerBg}`}>
                <div className="text-xs font-bold text-slate-500 uppercase">{DAYS_OF_WEEK[index]}</div>
                <div className={`text-sm font-bold ${isToday ? (themeColor === 'blue' ? 'text-blue-600' : 'text-orange-600') : 'text-slate-700'}`}>
                  {day.getDate()}/{day.getMonth() + 1}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Scrollable Body: Time Slots */}
      <div className="overflow-y-auto flex-1">
        {HOURS.map((time, timeIndex) => (
          <div key={time} className="flex border-b border-slate-100 min-h-[60px]">
            {/* Time Label */}
            <div className="w-20 flex-shrink-0 p-2 text-xs font-bold text-slate-400 border-r border-slate-200 flex items-start justify-center pt-3 bg-slate-50/50">
              {time}
            </div>

            {/* Day Columns for this Time */}
            <div className="flex-1 grid grid-cols-7 divide-x divide-slate-100">
              {weekDays.map((day, dayIndex) => {
                const reservation = getReservationForSlot(day, time);
                const isStartOfReservation = reservation && reservation.startTime === time;

                return (
                  <div 
                    key={dayIndex} 
                    className={`relative p-1 transition-colors ${!reservation ? 'hover:bg-slate-50 cursor-pointer' : ''}`}
                    onClick={() => !reservation && onSlotClick(day, time)}
                  >
                    {reservation ? (
                      // Only render content if it's the start block or the block exists
                      // To make it look like one continuous block, we style it fully
                      <div 
                        onClick={(e) => { e.stopPropagation(); onEventClick && onEventClick(reservation); }}
                        className={`w-full h-full text-[10px] p-1 rounded-sm cursor-pointer shadow-sm overflow-hidden leading-tight ${getEventStyle()}`}
                        title={`${reservation.resourceName} - ${reservation.requester}`}
                      >
                        {/* Only show text on the first block of the reservation to avoid repetition */}
                        {isStartOfReservation && (
                          <>
                            <div className="font-bold truncate">{reservation.resourceName}</div>
                            <div className="truncate opacity-80">{reservation.requester}</div>
                          </>
                        )}
                      </div>
                    ) : (
                      <div className="h-full w-full"></div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        ))}
        {/* Padding at bottom */}
        <div className="h-10"></div>
      </div>
    </div>
  );
};

export default CalendarView;

import React, { useState, useEffect } from 'react';
import { FaPlus, FaTrash, FaTools, FaInfoCircle, FaLock, FaExclamationTriangle } from 'react-icons/fa';
import CalendarView from '../components/CalendarView';
import Modal from '../components/Modal';
import { HOURS, MASTER_PASSWORD } from '../constants';
import { Equipment, Reservation } from '../types';
import * as reservationService from '../services/reservationService';

const Workshop: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [equipmentList, setEquipmentList] = useState<Equipment[]>([]);
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(false);

  // Modal States
  const [isReservationModalOpen, setIsReservationModalOpen] = useState(false);

  // Password Modal State
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);
  const [deletePassword, setDeletePassword] = useState('');
  const [passwordError, setPasswordError] = useState(false);

  // Selected reservation for details
  const [selectedReservation, setSelectedReservation] = useState<Reservation | null>(null);

  // Form State
  const [formData, setFormData] = useState({
    resourceId: '',
    date: '',
    startTime: '',
    endTime: '',
    requester: '',
    observation: ''
  });

  useEffect(() => {
    loadData();
  }, [currentDate]);

  const loadData = async () => {
    setLoading(true);
    try {
      const equip = await reservationService.getEquipment(false);
      setEquipmentList(equip.filter(e => e.type !== 'vehicle'));

      const allRes = await reservationService.getAllReservations();
      setReservations(allRes.filter(r => r.type === 'workshop'));
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  // --- Date Navigation (Weekly) ---
  const handlePrevWeek = () => {
    const newDate = new Date(currentDate);
    newDate.setDate(newDate.getDate() - 7);
    setCurrentDate(newDate);
  };

  const handleNextWeek = () => {
    const newDate = new Date(currentDate);
    newDate.setDate(newDate.getDate() + 7);
    setCurrentDate(newDate);
  };

  const handleToday = () => {
    setCurrentDate(new Date());
  };

  // --- Modal Logic ---
  const openNewReservation = (date?: Date, time?: string) => {
    const d = date || new Date();
    // Default to next hour if not specified
    let startT = time || '08:00';

    // Auto calculate end time (1 hour duration default)
    const hourIndex = HOURS.indexOf(startT);
    let endT = '';
    if (hourIndex !== -1 && hourIndex < HOURS.length - 1) {
        endT = HOURS[hourIndex + 1];
    } else {
        endT = HOURS[HOURS.length - 1]; // Max limit
    }

    setFormData({
      resourceId: '',
      date: d.toISOString().split('T')[0],
      startTime: startT,
      endTime: endT,
      requester: '',
      observation: ''
    });
    setSelectedReservation(null);
    setIsReservationModalOpen(true);
  };

  const handleSlotClick = (date: Date, time: string) => {
    openNewReservation(date, time);
  };

  const handleEventClick = (res: Reservation) => {
    setSelectedReservation(res);
    // Don't open the form modal, maybe show details or just allow delete from a small popup?
    // For now, let's open a detail view inside the modal using the form but read-only or pre-filled?
    // User requested "delete" functionality mainly.
    // Let's reuse the modal logic but show it as "Details".
    setFormData({
        resourceId: res.resourceId,
        date: res.date,
        startTime: res.startTime,
        endTime: res.endTime,
        requester: res.requester,
        observation: res.observation || ''
    });
    setIsReservationModalOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    // If we are in "View Mode" (selectedReservation exists), maybe we don't save?
    // Or we treat it as an edit? For now, let's just handle Create. 
    // If selectedReservation exists, we block creation to avoid duplicates or implement Edit logic later.
    if (selectedReservation) {
        alert("Edição não suportada ainda. Exclua e crie novamente.");
        return;
    }

    const resource = equipmentList.find(e => e.id === formData.resourceId);

    try {
      await reservationService.createReservation({
        resourceId: formData.resourceId,
        resourceName: resource?.name || 'Desconhecido',
        type: 'workshop',
        date: formData.date,
        startTime: formData.startTime,
        endTime: formData.endTime,
        requester: formData.requester,
        observation: formData.observation
      });
      alert("Reserva realizada com sucesso!");
      loadData();
      setIsReservationModalOpen(false);
    } catch (err: any) {
      alert(err.message);
    }
  };

  // --- Delete Logic ---
  const requestDelete = () => {
    if (!selectedReservation) return;
    setItemToDelete(selectedReservation.id);
    setDeletePassword('');
    setPasswordError(false);
    setShowDeleteConfirm(true);
  };

  const confirmDelete = async (e: React.FormEvent) => {
    e.preventDefault();
    if (deletePassword !== MASTER_PASSWORD) {
        setPasswordError(true);
        return;
    }
    if (!itemToDelete) return;

    try {
      setReservations(prev => prev.filter(r => r.id !== itemToDelete));
      setShowDeleteConfirm(false);
      setIsReservationModalOpen(false); // Close details modal
      await reservationService.deleteReservation(itemToDelete);
      loadData();
    } catch (error) {
      console.error("Erro ao excluir", error);
      alert("Erro ao excluir. Tente novamente.");
      loadData();
    }
  };

  // Helper for Header Date Range
  const getWeekRangeString = () => {
    const d = new Date(currentDate);
    const day = d.getDay();
    const start = new Date(d);
    start.setDate(d.getDate() - day);
    const end = new Date(start);
    end.setDate(start.getDate() + 6);

    return `${start.getDate()} ${start.toLocaleDateString('pt-BR', {month:'short'})} - ${end.getDate()} ${end.toLocaleDateString('pt-BR', {month:'short'})}`;
  };

  return (
    <div className="p-4 md:p-8 h-screen flex flex-col">
      <header className="mb-6 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 flex-shrink-0">
        <div>
          <h1 className="text-3xl font-bold text-slate-800">Oficina Mecânica</h1>
          <p className="text-slate-500 mt-1">Gestão visual de ocupação.</p>
        </div>

        <div className="flex flex-col md:flex-row gap-3 w-full md:w-auto items-center">
             <button 
                onClick={() => openNewReservation()}
                className="bg-blue-600 text-white px-6 py-2 rounded-lg shadow-lg hover:bg-blue-700 font-bold flex items-center justify-center gap-2 transition-transform active:scale-95"
            >
                <FaPlus /> Nova Reserva
            </button>

            <div className="flex gap-2 bg-white p-1 rounded-lg shadow-sm border border-slate-200 items-center">
                <button onClick={handlePrevWeek} className="px-3 py-1.5 text-slate-600 hover:bg-slate-100 rounded text-sm font-medium">Anterior</button>
                <span className="px-2 py-1.5 font-bold text-slate-800 min-w-[140px] text-center border-x border-slate-100 flex flex-col justify-center leading-tight cursor-pointer hover:bg-slate-50" onClick={handleToday} title="Ir para Hoje">
                    <span className="text-xs text-slate-400 uppercase">Semana de</span>
                    <span>{getWeekRangeString()}</span>
                </span>
                <button onClick={handleNextWeek} className="px-3 py-1.5 text-slate-600 hover:bg-slate-100 rounded text-sm font-medium">Próximo</button>
            </div>
        </div>
      </header>

      {loading ? <div className="text-center py-10">Carregando...</div> : (
        <>
            <div className="flex items-center gap-2 mb-2 text-xs text-slate-500 bg-blue-50 p-2 rounded border border-blue-100 w-fit">
                <FaInfoCircle className="text-blue-500" />
