import React, { useState, useEffect } from 'react';
import { FaCogs, FaPlus, FaTrash, FaMoneyBillWave } from 'react-icons/fa';
import CalendarView from '../components/CalendarView';
import Modal from '../components/Modal';
import { HOURS, MASTER_PASSWORD } from '../constants';
import { Equipment, Reservation } from '../types';
import * as reservationService from '../services/reservationService';

const Machining: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [machines, setMachines] = useState<Equipment[]>([]);
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(false);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedReservation, setSelectedReservation] = useState<Reservation | null>(null);

  const [formData, setFormData] = useState({
    resourceId: '',
    date: '',
    startTime: '',
    endTime: '',
    requester: '',
    observation: '',
    costSaved: 0
  });

  const [deletePassword, setDeletePassword] = useState('');
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  useEffect(() => {
    loadData();
  }, [currentDate]);

  const loadData = async () => {
    setLoading(true);
    try {
      const allEquip = await reservationService.getEquipment(true);
      // Assuming machines for REC are categorized as 'machine' but we can filter specific names if we want, 
      // or user can create a new type. For V1 let's use 'machine' and user filters by name in UI or separate type later.
      // For now, I'll show all 'machine' types here too or user can create 'rec_machine' in future.
      // Let's rely on Settings to define what machines are available.
      setMachines(allEquip.filter(e => e.type === 'machine')); 

      const allRes = await reservationService.getAllReservations();
      setReservations(allRes.filter(r => r.type === 'machining'));
    } finally {
      setLoading(false);
    }
  };

  const handlePrevWeek = () => { const d = new Date(currentDate); d.setDate(d.getDate() - 7); setCurrentDate(d); };
  const handleNextWeek = () => { const d = new Date(currentDate); d.setDate(d.getDate() + 7); setCurrentDate(d); };

  const openNewReservation = (date?: Date, time?: string) => {
    const d = date || new Date();
    let startT = time || '08:00';
    const hourIndex = HOURS.indexOf(startT);
    let endT = (hourIndex !== -1 && hourIndex < HOURS.length - 1) ? HOURS[hourIndex + 1] : HOURS[HOURS.length - 1];

    setFormData({
      resourceId: '',
      date: d.toISOString().split('T')[0],
      startTime: startT,
      endTime: endT,
      requester: '',
      observation: '',
      costSaved: 0
    });
    setSelectedReservation(null);
    setIsModalOpen(true);
  };

  const handleSlotClick = (date: Date, time: string) => openNewReservation(date, time);
  const handleEventClick = (res: Reservation) => {
    setSelectedReservation(res);
    setFormData({
        resourceId: res.resourceId,
        date: res.date,
        startTime: res.startTime,
        endTime: res.endTime,
        requester: res.requester,
        observation: res.observation || '',
        costSaved: res.costSaved || 0
    });
    setIsModalOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedReservation) return alert("Edição não suportada.");
    const machine = machines.find(m => m.id === formData.resourceId);
    try {
      await reservationService.createReservation({
        resourceId: formData.resourceId,
        resourceName: machine?.name || 'Máquina',
        type: 'machining',
        date: formData.date,
        startTime: formData.startTime,
        endTime: formData.endTime,
        requester: formData.requester,
        observation: formData.observation,
        costSaved: Number(formData.costSaved)
      });
      alert("Serviço agendado!");
      loadData();
      setIsModalOpen(false);
    } catch (err: any) {
      alert(err.message);
    }
  };

  const confirmDelete = async (e: React.FormEvent) => {
    e.preventDefault();
    if (deletePassword !== MASTER_PASSWORD) return alert("Senha incorreta");
    if (selectedReservation) {
        await reservationService.deleteReservation(selectedReservation.id);
        setShowDeleteConfirm(false);
        setIsModalOpen(false);
        loadData();
    }
  };

  return (
    <div className="p-8 h-screen flex flex-col bg-slate-200">
        <header className="mb-6 flex justify-between items-center">
            <div>
                <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-2">
                    <FaCogs className="text-slate-600" /> REC (Usinagem)
                </h1>
                <p className="text-slate-600 mt-1">Programação de Torno e Fresa CNC.</p>
            </div>
            <div className="flex gap-3">
                <button onClick={() => openNewReservation()} className="bg-slate-700 hover:bg-slate-800 text-white px-6 py-2 rounded-lg font-bold shadow flex gap-2 items-center">
                    <FaPlus /> Novo Serviço
                </button>
                <div className="flex gap-2 bg-white p-1 rounded-lg border shadow-sm">
                    <button onClick={handlePrevWeek} className="px-3 hover:bg-slate-100 rounded">Anterior</button>
                    <button onClick={handleNextWeek} className="px-3 hover:bg-slate-100 rounded">Próximo</button>
                </div>
            </div>
        </header>

        {loading ? <div>Carregando...</div> : (
             <div className="flex-1 overflow-hidden">
                <CalendarView 
                    currentDate={currentDate}
                    onSlotClick={handleSlotClick}
                    onEventClick={handleEventClick}
                    reservations={reservations}
                    themeColor="orange"
                />
             </div>
        )}

        <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)}>
            <div className="p-6 bg-white rounded-lg">
                <h2 className="text-xl font-bold text-slate-700 mb-4 flex items-center gap-2">
                    <FaCogs /> {selectedReservation ? 'Detalhes do Serviço' : 'Novo Serviço de Usinagem'}
                </h2>

                {selectedReservation && (
                     <button onClick={() => setShowDeleteConfirm(true)} className="text-red-500 text-sm font-bold flex gap-1 items-center mb-4"><FaTrash/> Excluir</button>
                )}

                {!showDeleteConfirm ? (
                <form onSubmit={handleSubmit} className="space-y-4">
                     <div>
                        <label className="block text-xs font-bold text-slate-500 mb-1">Máquina (Torno/Fresa)</label>
                        <select className="w-full p-2 border rounded" value={formData.resourceId} onChange={e => setFormData({...formData, resourceId: e.target.value})} disabled={!!selectedReservation}>
                            <option value="">Selecione...</option>
                            {machines.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
                        </select>
                     </div>
                     <div className="grid grid-cols-2 gap-2">
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Data</label>
                            <input type="date" className="w-full p-2 border rounded" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} disabled={!!selectedReservation} />
                        </div>
                         <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Solicitante</label>
                            <input type="text" className="w-full p-2 border rounded" value={formData.requester} onChange={e => setFormData({...formData, requester: e.target.value})} disabled={!!selectedReservation} />
                        </div>
                     </div>
                     <div className="grid grid-cols-2 gap-2">
                        <div>
                             <label className="block text-xs font-bold text-slate-500 mb-1">Início</label>
                             <select className="w-full p-2 border rounded" value={formData.startTime} onChange={e => setFormData({...formData, startTime: e.target.value})} disabled={!!selectedReservation}>
                                 {HOURS.map(h => <option key={h} value={h}>{h}</option>)}
                             </select>
                        </div>
                        <div>
                             <label className="block text-xs font-bold text-slate-500 mb-1">Fim</label>
                             <select className="w-full p-2 border rounded" value={formData.endTime} onChange={e => setFormData({...formData, endTime: e.target.value})} disabled={!!selectedReservation}>
                                 {HOURS.map(h => <option key={h} value={h}>{h}</option>)}
                             </select>
                        </div>
                     </div>
                     <div>
                        <label className="block text-xs font-bold text-slate-500 mb-1">Peça / Serviço a Executar</label>
                        <input className="w-full p-2 border rounded" value={formData.observation} onChange={e => setFormData({...formData, observation: e.target.value})} disabled={!!selectedReservation} />
                     </div>
                     <div>
                        <label className="block text-xs font-bold text-green-600 mb-1 flex items-center gap-1"><FaMoneyBillWave/> Custo Evitado (R$)</label>
                        <input type="number" step="0.01" className="w-full p-2 border border-green-200 bg-green-50 rounded" value={formData.costSaved} onChange={e => setFormData({...formData, costSaved: Number(e.target.value)})} disabled={!!selectedReservation} placeholder="0.00" />
                     </div>

                     {!selectedReservation && <button type="submit" className="w-full bg-slate-800 text-white font-bold py-2 rounded hover:bg-slate-900">Agendar</button>}
                </form>
                ) : (
                    <form onSubmit={confirmDelete} className="bg-red-50 p-4 rounded border border-red-100">
                        <input type="password" value={deletePassword} onChange={e => setDeletePassword(e.target.value)} className="w-full p-2 border rounded mb-2" placeholder="Senha mestre" />
                        <div className="flex gap-2">
                            <button type="button" onClick={() => setShowDeleteConfirm(false)} className="flex-1 bg-slate-200 py-2 rounded">Cancelar</button>
                            <button type="submit" className="flex-1 bg-red-600 text-white py-2 rounded font-bold">Excluir</button>
                        </div>
                    </form>
                )}
            </div>
        </Modal>
    </div>
  );
};

export default Machining;

import React, { useState, useEffect } from 'react';
import { FaBolt, FaMicrochip, FaPlus, FaCheck, FaTrash, FaMoneyBillWave, FaExclamationTriangle } from 'react-icons/fa';
import Modal from '../components/Modal';
import { MaintenanceOrder } from '../types';
import * as reservationService from '../services/reservationService';
import { MASTER_PASSWORD } from '../constants';

interface RepairManagerProps {
  type: 'motor' | 'board';
}

const RepairManager: React.FC<RepairManagerProps> = ({ type }) => {
  const [orders, setOrders] = useState<MaintenanceOrder[]>([]);
  const [loading, setLoading] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const [formData, setFormData] = useState<Partial<MaintenanceOrder>>({
    itemName: '', description: '', status: 'pending', costSaved: 0, technician: ''
  });

  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [deletePassword, setDeletePassword] = useState('');

  const isMotor = type === 'motor';
  const ThemeIcon = isMotor ? FaBolt : FaMicrochip;
  const themeColor = isMotor ? 'text-yellow-600' : 'text-emerald-600';
  const bgColor = isMotor ? 'bg-yellow-50' : 'bg-emerald-50';
  const btnColor = isMotor ? 'bg-yellow-600 hover:bg-yellow-700' : 'bg-emerald-600 hover:bg-emerald-700';

  useEffect(() => {
    loadData();
  }, [type]);

  const loadData = async () => {
    setLoading(true);
    try {
        const data = await reservationService.getMaintenanceOrders(type);
        setOrders(data.sort((a,b) => new Date(b.entryDate).getTime() - new Date(a.entryDate).getTime()));
    } finally {
        setLoading(false);
    }
  };

  const handleCreate = () => {
      setFormData({ itemName: '', description: '', status: 'pending', costSaved: 0, technician: '' });
      setIsModalOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
        await reservationService.saveMaintenanceOrder({
            id: '',
            type,
            itemName: formData.itemName!,
            description: formData.description!,
            status: formData.status as any,
            costSaved: Number(formData.costSaved),
            technician: formData.technician,
            entryDate: new Date().toISOString().split('T')[0]
        });
        loadData();
        setIsModalOpen(false);
    } catch (e) {
        alert("Erro ao salvar");
    }
  };

  const handleStatusChange = async (order: MaintenanceOrder, newStatus: 'in_progress' | 'completed') => {
      // If completing, maybe ask for Cost Saved? For now, simplistic toggle.
      const updated = { ...order, status: newStatus, completionDate: newStatus === 'completed' ? new Date().toISOString().split('T')[0] : undefined };
      await reservationService.saveMaintenanceOrder(updated);
      loadData();
  };

  const handleDelete = async (e: React.FormEvent) => {
      e.preventDefault();
      if (deletePassword !== MASTER_PASSWORD) return alert("Senha incorreta");
      if (deleteId) {
          await reservationService.deleteMaintenanceOrder(deleteId);
          setDeleteId(null);
          loadData();
      }
  };

  const getStatusBadge = (status: string) => {
      if (status === 'completed') return <span className="px-2 py-1 bg-green-100 text-green-700 rounded text-xs font-bold">Concluído</span>;
      if (status === 'in_progress') return <span className="px-2 py-1 bg-blue-100 text-blue-700 rounded text-xs font-bold">Em Andamento</span>;
      return <span className="px-2 py-1 bg-slate-100 text-slate-600 rounded text-xs font-bold">Pendente</span>;
  };

  return (
    <div className={`p-8 h-screen flex flex-col ${bgColor} overflow-y-auto`}>
       <header className="mb-6 flex justify-between items-center">
            <div>
                <h1 className={`text-3xl font-bold flex items-center gap-2 text-slate-800`}>
                    <ThemeIcon className={themeColor} /> 
                    {isMotor ? 'Sala de Motores' : 'Sala de Placas'}
                </h1>
                <p className={`${themeColor} mt-1 opacity-80`}>Gestão de manutenção e rebobinamento.</p>
            </div>
            <button onClick={handleCreate} className={`${btnColor} text-white px-6 py-2 rounded-lg font-bold shadow flex gap-2 items-center transition-transform active:scale-95`}>
                <FaPlus /> Novo Item
            </button>
        </header>

        {loading ? <div>Carregando...</div> : (
            <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-4">
                {orders.map(order => (
                    <div key={order.id} className="bg-white p-5 rounded-xl shadow-sm border border-slate-100 flex flex-col justify-between hover:shadow-md transition-shadow">
                        <div>
                            <div className="flex justify-between items-start mb-2">
                                <h3 className="font-bold text-lg text-slate-800">{order.itemName}</h3>
                                {getStatusBadge(order.status)}
                            </div>
                            <p className="text-sm text-slate-500 mb-4">{order.description}</p>

                            <div className="text-xs text-slate-400 space-y-1">
                                <p>Entrada: {new Date(order.entryDate + 'T12:00:00').toLocaleDateString()}</p>
                                {order.completionDate && <p>Saída: {new Date(order.completionDate + 'T12:00:00').toLocaleDateString()}</p>}
                                {order.technician && <p>Técnico: {order.technician}</p>}
                            </div>

                            {order.costSaved > 0 && (
                                <div className="mt-3 p-2 bg-green-50 border border-green-100 rounded flex items-center gap-2 text-green-700 font-bold text-sm">
                                    <FaMoneyBillWave /> R$ {order.costSaved.toFixed(2)}
                                </div>
                            )}
                        </div>

                        <div className="mt-4 pt-4 border-t border-slate-100 flex justify-between items-center">
                            <button onClick={() => setDeleteId(order.id)} className="text-slate-300 hover:text-red-500 transition-colors">
                                <FaTrash />
                            </button>

                            <div className="flex gap-2">
                                {order.status === 'pending' && (
                                    <button onClick={() => handleStatusChange(order, 'in_progress')} className="text-xs font-bold text-blue-600 hover:bg-blue-50 px-3 py-1 rounded border border-blue-200">
                                        Iniciar
                                    </button>
                                )}
                                {order.status !== 'completed' && (
                                    <button onClick={() => handleStatusChange(order, 'completed')} className="text-xs font-bold text-green-600 hover:bg-green-50 px-3 py-1 rounded border border-green-200 flex items-center gap-1">
                                        <FaCheck /> Concluir
                                    </button>
                                )}
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        )}

        <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)}>
            <div className="p-6 bg-white rounded-lg">
                <h2 className="text-xl font-bold text-slate-800 mb-4">Novo Registro</h2>
                <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                        <label className="block text-xs font-bold text-slate-500 mb-1">Item (Tag/Nome)</label>
                        <input className="w-full p-2 border rounded" value={formData.itemName} onChange={e => setFormData({...formData, itemName: e.target.value})} placeholder="Ex: Motor Bomba 501" required />
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-slate-500 mb-1">Motivo / Defeito</label>
                        <textarea className="w-full p-2 border rounded" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} placeholder="Ex: Queima por sobrecarga..." rows={3} />
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                         <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Custo Evitado (R$)</label>
                            <input type="number" step="0.01" className="w-full p-2 border rounded" value={formData.costSaved} onChange={e => setFormData({...formData, costSaved: Number(e.target.value)})} placeholder="0.00" />
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Técnico Responsável</label>
                            <input className="w-full p-2 border rounded" value={formData.technician} onChange={e => setFormData({...formData, technician: e.target.value})} />
                        </div>
                    </div>
                    <button type="submit" className={`w-full ${btnColor} text-white font-bold py-3 rounded mt-2`}>Salvar Registro</button>
                </form>
            </div>
        </Modal>

        {/* Delete Confirmation */}
        {deleteId && (
            <div className="fixed inset-0 z-[60] flex items-center justify-center bg-slate-900/50 backdrop-blur-sm">
                <div className="bg-white p-6 rounded-lg shadow-xl w-80">
                    <h3 className="font-bold text-red-600 mb-2 flex items-center gap-2"><FaExclamationTriangle/> Confirmar Exclusão</h3>
                    <form onSubmit={handleDelete}>
                        <input type="password" autoFocus placeholder="Senha mestre" className="w-full p-2 border rounded mb-3" value={deletePassword} onChange={e => setDeletePassword(e.target.value)} />
                        <div className="flex gap-2">
                             <button type="button" onClick={() => { setDeleteId(null); setDeletePassword(''); }} className="flex-1 bg-slate-100 py-2 rounded">Cancelar</button>
                             <button type="submit" className="flex-1 bg-red-600 text-white py-2 rounded font-bold">Excluir</button>
                        </div>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

export default RepairManager;

import React, { useState, useEffect } from 'react';
import { FaPen, FaPlus, FaCloud, FaSave, FaTimes, FaTools, FaSnowflake, FaCogs } from 'react-icons/fa';
import * as reservationService from '../services/reservationService';
import { isSupabaseConfigured } from '../services/supabaseClient';
import { Equipment } from '../types';

const Settings: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'oficina' | 'refrigeracao' | 'rec'>('oficina');
  const [equipment, setEquipment] = useState<Equipment[]>([]);

  // Form State
  const [eqName, setEqName] = useState('');
  const [eqType, setEqType] = useState('machine');
  const [editingId, setEditingId] = useState<string | null>(null);

  const [isConnected, setIsConnected] = useState(false);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    load();
    setIsConnected(isSupabaseConfigured());
  }, []);

  const load = async () => {
    setLoading(true);
    try {
        const data = await reservationService.getEquipment(true);
        setEquipment(data);
    } catch (error) {
        console.error("Error loading equipment:", error);
    } finally {
        setLoading(false);
    }
  };

  const filteredEquipment = equipment.filter(e => {
      if (activeTab === 'oficina') return e.type === 'machine' || e.type === 'tool' || e.type === 'vehicle';
      if (activeTab === 'refrigeracao') return e.type === 'area';
      // For REC we share 'machine' type but maybe in future distinguish. 
      // For V1 let's assume REC uses 'machine' too, but maybe user wants to see them all in 'oficina'.
      // To separate, let's just filter by what context we are in? 
      // Actually, let's keep it simple: Oficina manages Machines/Tools. Refrig manages Areas.
      return false;
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!eqName) return;

    setLoading(true);
    try {
        const existing = equipment.find(e => e.id === editingId);
        // Force type based on tab if creating new
        let typeToSave = eqType;
        if (activeTab === 'refrigeracao') typeToSave = 'area';

        await reservationService.saveEquipment({
            id: editingId || '',
            name: eqName,
            type: typeToSave as any,
            isActive: existing ? existing.isActive : true
        });

        setEqName('');
        setEditingId(null);
        await load(); 
    } catch (e) {
        console.error(e);
        alert("Erro ao salvar.");
    } finally {
        setLoading(false);
    }
  };

  const handleEditClick = (eq: Equipment) => {
      setEditingId(eq.id);
      setEqName(eq.name);
      setEqType(eq.type);
      window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleToggleStatus = async (eq: Equipment) => {
      const newStatus = !eq.isActive;
      setEquipment(prev => prev.map(e => e.id === eq.id ? { ...e, isActive: newStatus } : e));
      try {
          await reservationService.saveEquipment({ ...eq, isActive: newStatus });
          load();
      } catch (e) {
          setEquipment(prev => prev.map(e => e.id === eq.id ? { ...e, isActive: !newStatus } : e));
      }
  };

  return (
    <div className="p-8 h-screen overflow-y-auto bg-slate-50">
      <div className="flex justify-between items-center mb-6">
          <h1 className="text-3xl font-bold text-slate-800">Configurações</h1>
          <div className={`flex items-center gap-2 px-3 py-1 rounded-full text-sm font-bold border ${isConnected ? 'bg-green-100 text-green-700 border-green-200' : 'bg-red-100 text-red-700 border-red-200'}`}>
                <FaCloud />
                {isConnected ? 'Conectado' : 'Offline'}
          </div>
      </div>

      {/* TABS */}
      <div className="flex gap-4 mb-6 border-b border-slate-200">
          <button onClick={() => setActiveTab('oficina')} className={`pb-2 px-4 font-bold flex items-center gap-2 ${activeTab === 'oficina' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'}`}>
              <FaTools /> Equipamentos (Oficina/REC)
          </button>
          <button onClick={() => setActiveTab('refrigeracao')} className={`pb-2 px-4 font-bold flex items-center gap-2 ${activeTab === 'refrigeracao' ? 'text-cyan-600 border-b-2 border-cyan-600' : 'text-slate-400'}`}>
              <FaSnowflake /> Áreas (Refrigeração)
          </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">

        {/* Form */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 h-fit">
          <h2 className="text-xl font-bold text-slate-700 mb-4">{editingId ? 'Editar Item' : 'Adicionar Item'}</h2>

          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Nome</label>
              <input value={eqName} onChange={e => setEqName(e.target.value)} className="w-full p-2 border rounded" placeholder={activeTab === 'refrigeracao' ? 'Ex: Linha 501' : 'Ex: Torno Mecânico'} disabled={loading} />
            </div>

            {activeTab === 'oficina' && (
                <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Tipo</label>
                <select value={eqType} onChange={e => setEqType(e.target.value)} className="w-full p-2 border rounded" disabled={loading}>
                    <option value="machine">Máquina</option>
                    <option value="tool">Ferramenta</option>
                    <option value="vehicle">Veículo</option>
                </select>
                </div>
            )}

            <button type="submit" className="w-full bg-blue-600 text-white font-bold py-3 rounded hover:bg-blue-700 transition-colors">
                {editingId ? 'Salvar Alterações' : 'Adicionar'}
            </button>
            {editingId && <button type="button" onClick={() => {setEditingId(null); setEqName('');}} className="w-full mt-2 text-slate-400 text-sm">Cancelar</button>}
          </form>
        </div>

        {/* List */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h2 className="text-xl font-bold text-slate-700 mb-4">Itens Cadastrados</h2>
          <div className="space-y-2 max-h-[500px] overflow-y-auto">
            {filteredEquipment.length > 0 ? filteredEquipment.map(eq => (
                <div key={eq.id} className={`flex justify-between items-center p-3 rounded border ${eq.isActive ? 'bg-white' : 'bg-slate-50'}`}>
                    <div>
                        <span className={`font-semibold block ${eq.isActive ? 'text-slate-700' : 'text-slate-400 line-through'}`}>{eq.name}</span>
                        <span className="text-[10px] text-slate-400 font-bold uppercase">{eq.type}</span>
                    </div>
                    <div className="flex gap-2">
                        <button onClick={() => handleToggleStatus(eq)} className={`px-2 py-1 text-xs rounded font-bold ${eq.isActive ? 'bg-green-100 text-green-700' : 'bg-slate-200 text-slate-500'}`}>{eq.isActive ? 'Ativo' : 'Inativo'}</button>
                        <button onClick={() => handleEditClick(eq)} className="px-2 py-1 bg-blue-50 text-blue-600 rounded"><FaPen size={10}/></button>
                    </div>
                </div>
            )) : <p className="text-slate-400 italic">Nenhum item.</p>}
          </div>
        </div>

      </div>
    </div>
  );
};

export default Settings;

import React from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Workshop from './pages/Workshop';
import Scaffolding from './pages/Scaffolding';
import Reports from './pages/Reports';
import Settings from './pages/Settings';
import Refrigeration from './pages/Refrigeration';
import RepairManager from './pages/RepairManager';
import Machining from './pages/Machining';

const App: React.FC = () => {
  return (
    <HashRouter>
      <div className="flex bg-slate-100 h-screen font-sans">
        <Sidebar />
        <main className="flex-1 overflow-hidden">
          <Routes>
            <Route path="/" element={<Workshop />} />
            <Route path="/scaffolding" element={<Scaffolding />} />

            {/* New Modules */}
            <Route path="/refrigeration" element={<Refrigeration />} />
            <Route path="/motors" element={<RepairManager type="motor" />} />
            <Route path="/boards" element={<RepairManager type="board" />} />
